window.docContents[139].resolve({"/Imp/#Hoare-Logic--Imp___-Simple-Imperative-Programs--Evaluating-Commands--Determinism-of-Evaluation":{"contents":"\n\nChanging from a computational to a relational definition of evaluation\nis a good move because it frees us from the artificial requirement that\nevaluation be a total function. But it raises a question: is the\nrelational definition really a partial function? Could the same\ncommand, from the same state, evaluate to two different final states?\nIn fact this cannot happen: ceval is a partial function.\n\n\n\n\n\ntheorem ceval_deterministic {c : Com} {st st1 st2 : State}\n    (e₁ : st =[ ~c ]=> st1) (e₂ : st =[ ~c ]=> st2) : st1 = st2 := by\n  induction e₁ generalizing st2 with\n  | @skip st =>\n    inversion e₂\n    rfl\n  | @asgn st a n x h =>\n    inversion e₂ with\n    | asgn h' =>\n      subst h h'\n      rfl\n  | @seq c₁ c₂ st st' st'' h₁ h₂ ih₁ ih₂ =>\n    inversion e₂ with\n    | seq st2' h₁' h₂' =>\n      have hst : st' = st2' := ih₁ h₁'\n      subst hst\n      exact ih₂ h₂'\n  | @ifTrue st st' b c₁ c₂ hb hc ih =>\n    inversion e₂ with\n    | ifTrue hb' hc' => exact ih hc'\n    | ifFalse hb' hc' => simp_all\n  | @ifFalse st st' b c₁ c₂ hb hc ih =>\n    inversion e₂ with\n    | ifTrue hb' hc' => simp_all\n    | ifFalse hb' hc' => exact ih hc'\n  | @whileFalse b st c hb =>\n    inversion e₂ with\n    | whileFalse hb' => rfl\n    | whileTrue hb' hc' hl' => simp_all\n  | @whileTrue st st' st'' b c hb hc hloop ih₁ ih₂ =>\n    inversion e₂ with\n    | whileFalse hb' => simp_all\n    | whileTrue st2' _ hc' hl' =>\n      have hst : st' = st2' := ih₁ hc'\n      subst hst\n      exact ih₂ hl'\n\n\n\n\nWrite an Imp program that sums the numbers from 1 to X (inclusive)\nin the variable Y.  Your program should update the state as shown in\npup_to_2_ceval, which you can reverse-engineer to discover the program\nyou should write.  The proof of that theorem will be somewhat lengthy.def pupToN : Com := sorry\ntheorem pup_to_2_ceval :\n    {X ↦ 2} =[ ~pupToN ]=> {X ↦ 0, Y ↦ 3, X ↦ 1, Y ↦ 2, Y ↦ 0, X ↦ 2} := by\n  sorry\n\n\n\n\n","context":"Hoare Logic\u0009Imp: Simple Imperative Programs\u0009Evaluating Commands","header":"3.3.3. Determinism of Evaluation","id":"/Imp/#Hoare-Logic--Imp___-Simple-Imperative-Programs--Evaluating-Commands--Determinism-of-Evaluation"}});